func TestAccDataplexMetadataFeed_dataplexMetadataFeedBasicExample(t *testing.T) {
	t.Parallel()

	randomSuffix := acctest.RandString(t, 10)

	context := map[string]interface{}{
		"project_name":      envvar.GetTestProjectFromEnv(),
		"metadata_feed_id":  "tf-test-metadata-feed-basic" + randomSuffix,
		"pubsub_topic_name": "tf-test-metadata-feed-topic" + randomSuffix,
		"random_suffix":     randomSuffix,
	}

	acctest.VcrTest(t, resource.TestCase{
		PreCheck:                 func() { acctest.AccTestPreCheck(t) },
		ProtoV5ProviderFactories: acctest.ProtoV5ProviderFactories(t),
		CheckDestroy:             testAccCheckDataplexMetadataFeedDestroyProducer(t),
		Steps: []resource.TestStep{
			{
				Config: testAccDataplexMetadataFeed_dataplexMetadataFeedBasicExample(context),
			},
			{
				ResourceName:            "google_dataplex_metadata_feed.test_metadata_feed",
				ImportState:             true,
				ImportStateVerify:       true,
				ImportStateVerifyIgnore: []string{"labels", "location", "metadata_feed_id", "terraform_labels"},
			},
			{
				ResourceName:       "google_dataplex_metadata_feed.test_metadata_feed",
				RefreshState:       true,
				ExpectNonEmptyPlan: true,
				ImportStateKind:    resource.ImportBlockWithResourceIdentity,
			},
		},
	})
}

func testAccDataplexMetadataFeed_dataplexMetadataFeedBasicExample(context map[string]interface{}) string {
	return acctest.Nprintf(`
resource "google_pubsub_topic" "test_topic" {
  name = "%{pubsub_topic_name}"
}

resource "google_project_service_identity" "dataplex_identity" {
  project  = "%{project_name}"
  service  = "dataplex.googleapis.com"
}

resource "google_pubsub_topic_iam_member" "dataplex_publisher" {
  topic  = google_pubsub_topic.test_topic.name
  role   = "roles/pubsub.publisher"
  member = "serviceAccount:${google_project_service_identity.dataplex_identity.email}"
}

resource "google_pubsub_topic_iam_member" "dataplex_viewer" {
  topic  = google_pubsub_topic.test_topic.name
  role   = "roles/pubsub.viewer"
  member = "serviceAccount:${google_project_service_identity.dataplex_identity.email}"
}

resource "google_dataplex_metadata_feed" "test_metadata_feed" {
  metadata_feed_id = "%{metadata_feed_id}"
  project = "%{project_name}"
  location = "us-central1"
  scope {
    organization_level = true
  }
  pubsub_topic = google_pubsub_topic.test_topic.id

  depends_on = [
    google_pubsub_topic_iam_member.dataplex_publisher,
    google_pubsub_topic_iam_member.dataplex_viewer,
  ]
}

`, context)
}

func testAccCheckDataplexMetadataFeedDestroyProducer(t *testing.T) func(s *terraform.State) error {
	return func(s *terraform.State) error {
		for name, rs := range s.RootModule().Resources {
			if rs.Type != "google_dataplex_metadata_feed" {
				continue
			}
			if strings.HasPrefix(name, "data.") {
				continue
			}

			config := acctest.GoogleProviderConfig(t)
			url, err := tpgresource.ReplaceVarsForTest(config, rs, transport_tpg.BaseUrl(dataplex.Product, config)+"projects/{{project}}/locations/{{location}}/metadataFeeds/{{metadata_feed_id}}")
			if err != nil {
				return err
			}

			billingProject := ""

			if config.BillingProject != "" {
				billingProject = config.BillingProject
			}

			_, err = transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
				Config:    config,
				Method:    "GET",
				Project:   billingProject,
				RawURL:    url,
				UserAgent: config.UserAgent,
			})
			if err == nil {
				return fmt.Errorf("DataplexMetadataFeed still exists at %s", url)
			}
		}

		return nil
	}
}
